// ---------- Activity ----------
#[derive(Clone, Debug)]
struct Activity {
    start: NaiveDateTime,
    end: Option<NaiveDateTime>,
    project: String,
    description: String,
    line_num: usize, // 1-indexed for sanity/check messages
}

fn escape_field(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if c == '\\' { out.push_str("\\\\"); }
        else if c == '|' { out.push_str("\\|"); }
        else { out.push(c); }
    }
    out
}

fn unescape_and_trim(s: &str) -> String {
    // trim whitespace (spaces, tabs?) - original trims? Let's trim spaces and tabs
    // Actually file shows trimming of spaces. Use trim() which trims whitespace including \r?
    // But \r already stripped. Use trim().
    let t = s.trim();
    // unescape: \ + any char => that char, trailing \ alone => removed?
    let mut out = String::new();
    let mut chars = t.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(n) = chars.next() {
                out.push(n);
