#[derive(Clone)]
enum DateFilter {
    None,
    Today,
    Yesterday,
    CurrentWeek,
    LastWeek,
    Date(NaiveDate),
    Range(Option<NaiveDate>, Option<NaiveDate>),
}

fn week_bounds(date: NaiveDate, offset_weeks: i64) -> (NaiveDate, NaiveDate) {
    // Monday as start. date.weekday() Monday=0?
    let weekday = date.weekday().num_days_from_monday() as i64; // 0 Mon ..6 Sun
    let monday = date - Duration::days(weekday) + Duration::days(offset_weeks*7);
    let sunday = monday + Duration::days(6);
    (monday, sunday)
}

